async def act(page):
    """
    Dismiss any blocking dialog (scoped close via the dialog's close button) and
    then click the Save Order Address button to persist the address values that
    are already present on the page.

    Notes on knowledge-base helpers:
    - I inspected the available KB functions. They focus on dashboard extraction
      and CSV/reporting (dashboard snapshot, export orders CSV, etc.) and do
      not provide functionality for editing or saving an individual order
      address. Therefore none of the KB functions are applicable for this task
      and none are invoked.

    This function uses accessibility-role-centric selectors and scopes button
    clicks to parent roles when interacting with elements inside a dialog.
    The Save action is the final UI interaction because it may navigate away
    from the page.
    """

    async def safe_count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    # 1) If a dialog is present, attempt to close it by clicking a close button scoped
    #    inside the dialog. Use many candidate names to handle variations.
    dialog = page.get_by_role("dialog")
    if await safe_count(dialog) > 0:
        close_names = ["×", "X", "x", "Close", "close", "Cancel", "Dismiss", "OK"]
        closed = False
        for name in close_names:
            try:
                btn = dialog.get_by_role("button", name=name)
                if await safe_count(btn) > 0:
                    try:
                        await btn.first.click()
                        closed = True
                        await page.wait_for_timeout(300)
                        break
                    except Exception:
                        # try next candidate
                        pass
            except Exception:
                pass

        # Fallback: if no named close button succeeded, try clicking any button inside dialog
        if not closed:
            try:
                any_btn = dialog.get_by_role("button")
                if await safe_count(any_btn) > 0:
                    try:
                        await any_btn.first.click()
                        await page.wait_for_timeout(300)
                    except Exception:
                        # give up on dialog close attempts here; Escape below may help
                        pass
            except Exception:
                pass

    # 2) Use Escape presses to further attempt to dismiss overlays if they remain.
    try:
        for _ in range(3):
            await page.keyboard.press("Escape")
            await page.wait_for_timeout(250)
    except Exception:
        pass

    # 3) Click any top-level close-like buttons as another fallback (scoped at page level).
    top_close_names = ["×", "X", "x", "Close", "close", "Cancel", "Dismiss", "OK"]
    for name in top_close_names:
        try:
            btn = page.get_by_role("button", name=name)
            if await safe_count(btn) > 0:
                try:
                    await btn.first.click()
                    await page.wait_for_timeout(300)
                    break
                except Exception:
                    pass
        except Exception:
            pass

    # 4) Now perform the Save as the final action. Try the explicit label shown in the
    #    accessibility tree first, then fall back to common alternatives.
    save_candidates = [
        page.get_by_role("button", name="Save Order Address"),
        page.get_by_role("button", name="Save Order"),
        page.get_by_role("button", name="Save"),
    ]

    for btn in save_candidates:
        if await safe_count(btn) > 0:
            try:
                # This click may navigate away; do not perform further UI interactions after this.
                await btn.first.click()
                # Allow a short pause for the save/navigation to begin.
                await page.wait_for_timeout(1000)
                return
            except Exception:
                # try the next candidate
                continue

    # If we couldn't click Save, raise so external harness/human can inspect the blocking overlay.
    raise RuntimeError("Could not locate or click a Save button to persist the address for order #300.")

